using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using EmployeeAttendanceSystem.Data; using EmployeeAttendanceSystem.Models; using Microsoft.IdentityModel.Tokens;
namespace EmployeeAttendanceSystem.Services;
public class AuthService { readonly AppDbContext db; readonly IConfiguration config; public AuthService(AppDbContext db,IConfiguration config){this.db=db;this.config=config;} static string Hash(string s)=>Convert.ToBase64String(System.Security.Cryptography.Rfc2898DeriveBytes.Pbkdf2(s, Encoding.UTF8.GetBytes("EmployeeAttendanceSalt2026"), 100000, System.Security.Cryptography.HashAlgorithmName.SHA256, 32)); public (bool ok,string message,User? user,string? token) Register(string name,string email,string password){ if(string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(email)||password.Length<6)return(false,"Name, email and password (min 6 chars) are required",null,null); if(db.Users.Any(x=>x.Email.ToLower()==email.ToLower()))return(false,"Email already registered",null,null); var u=new User{Name=name,Email=email.ToLower(),PasswordHash=Hash(password),Role="Employee"}; db.Users.Add(u);db.SaveChanges();return(true,"Registration successful",u,Token(u)); } public (bool ok,string message,User? user,string? token) Login(string email,string password){var u=db.Users.FirstOrDefault(x=>x.Email.ToLower()==email.ToLower());if(u==null||u.PasswordHash!=Hash(password)||!u.IsActive)return(false,"Invalid credentials or inactive account",null,null);return(true,"Login successful",u,Token(u));} string Token(User u){var claims=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.Name),new Claim(ClaimTypes.Role,u.Role),new Claim(ClaimTypes.Email,u.Email)};var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]!));var cred=new SigningCredentials(key,SecurityAlgorithms.HmacSha256);var t=new JwtSecurityToken(claims:claims,expires:DateTime.UtcNow.AddHours(8),signingCredentials:cred);return new JwtSecurityTokenHandler().WriteToken(t);} }
